import re

# Let's first do a keyword-based check for apologies from the support agent
# and also look at the structure of dialogs more carefully

def get_agent_messages(dialog_text, company_id):
    """Extract messages from the support agent"""
    lines = dialog_text.split('\n\n')
    agent_msgs = []
    for line in lines:
        if line.startswith(company_id):
            agent_msgs.append(line)
    return agent_msgs

def has_apology_keyword(agent_messages):
    """Check if any agent message contains an apology keyword"""
    apology_patterns = [r'\bsorry\b', r'\bapologi', r'\bapology\b', r'\bapologies\b']
    for msg in agent_messages:
        for pattern in apology_patterns:
            if re.search(pattern, msg, re.IGNORECASE):
                return True
    return False

def get_customer_messages(dialog_text, company_id):
    """Extract messages from the customer"""
    lines = dialog_text.split('\n\n')
    customer_msgs = []
    for line in lines:
        if not line.startswith(company_id) and line.strip():
            customer_msgs.append(line)
    return customer_msgs

